
local R="rutas";if not fs.exists(R) then fs.makeDir(R) end;local function fuel() if turtle.getFuelLevel()=="unlimited" or turtle.getFuelLevel()>30 then return true end;local s=turtle.getSelectedSlot();turtle.select(16);local ok=turtle.refuel(1);turtle.select(s);return ok end;local function move(a) if a=="F" then return fuel() and turtle.forward() elseif a=="B" then return fuel() and turtle.back() elseif a=="U" then return fuel() and turtle.up() elseif a=="D" then return fuel() and turtle.down() elseif a=="L" then turtle.turnLeft();local ok=fuel() and turtle.forward();turtle.turnRight();return ok elseif a=="R" then turtle.turnRight();local ok=fuel() and turtle.forward();turtle.turnLeft();return ok end;return false end;local function collect() for i=1,15 do turtle.select(i);turtle.suck() end;turtle.select(1) end;local function deposit() for i=1,15 do turtle.select(i);turtle.drop() end;turtle.select(1) end;local function save(n,r) local f=fs.open(R.."/"..n..".txt.tmp","w");if not f then error("No se pudo guardar") end;f.write(textutils.serialize(r));f.close();if fs.exists(R.."/"..n..".txt") then fs.delete(R.."/"..n..".txt") end;fs.move(R.."/"..n..".txt.tmp",R.."/"..n..".txt");print("Ruta guardada: "..n) end;local function load(n) local f=fs.open(R.."/"..n..".txt","r");if not f then return nil end;local ok,r=pcall(textutils.unserialize,f.readAll());f.close();if not ok or type(r)~="table" then return nil end;return r end;local function record() term.clear();term.setCursorPos(1,1);print("NOMBRE DE LA RUTA:");local n=read():gsub("[^%w_%-]","");if n=="" then return end;local r={};while true do term.clear();term.setCursorPos(1,1);print("GRABANDO: "..n);print("F=Adelante B=Atras");print("L=Izquierda R=Derecha");print("U=Arriba D=Abajo");print("C=Recoger P=Depositar");print("S=Guardar X=Cancelar");write("Accion: ");local a=read():upper();if a=="S" then save(n,r);return elseif a=="X" then print("Grabacion cancelada");sleep(1);return elseif a=="C" then collect();table.insert(r,a) elseif a=="P" then deposit();table.insert(r,a) elseif a=="F" or a=="B" or a=="L" or a=="R" or a=="U" or a=="D" then if move(a) then table.insert(r,a) else print("MOVIMIENTO BLOQUEADO O SIN COMBUSTIBLE");sleep(2) end else print("Accion desconocida");sleep(1) end end end;local function execute(n) local r=load(n);if not r then print("Ruta invalida");sleep(2);return end;print("EJECUTANDO: "..n);print("CTRL+T PARA DETENER");while true do for i,a in ipairs(r) do if a=="C" then collect() elseif a=="P" then deposit() elseif not move(a) then print("ERROR EN PASO "..i.." - RUTA DETENIDA");return end end;sleep(1) end end;while true do term.clear();term.setCursorPos(1,1);print("=== TURTLE TRANSPORTADORA ===");print("1. GRABAR RUTA");print("2. EJECUTAR RUTA");print("3. LISTAR RUTAS");print("4. SALIR");write("Seleccion: ");local op=read();if op=="1" then record() elseif op=="2" then local files=fs.list(R);local names={};for _,v in ipairs(files) do if v:sub(-4)==".txt" then table.insert(names,v:sub(1,-5)) end end;term.clear();for i,n in ipairs(names) do print(i..". "..n) end;write("Numero de ruta: ");local k=tonumber(read());if k and names[k] then execute(names[k]) end elseif op=="3" then term.clear();print("=== RUTAS GUARDADAS ===");for _,v in ipairs(fs.list(R)) do print(v) end;print("ENTER para continuar");read() elseif op=="4" then break end end
